//! STUB(WP-015): a [`FeatureQueries`] answering from a table of clang 19's
//! answers to the queries that appear in the headers kiln is tested on
//! (`stub_features_table.rs`, generated by `scripts/gen-stub-features.py`).
//! Replace with WP-015's feature tables when they land.

use kiln_pp::{FeatureQueries, NoFeatures, TargetQuery};

use crate::toolchain::Target;

#[allow(clippy::unreadable_literal)]
#[path = "stub_features_table.rs"]
mod table;

/// Table-driven feature answers for one language and target.
#[allow(clippy::struct_excessive_bools)]
#[derive(Clone, Debug)]
pub struct StubFeatures {
    cplusplus: bool,
    cxx20: bool,
    exceptions: bool,
    rtti: bool,
    target: Target,
}

impl StubFeatures {
    /// Answers for C++ (`cplusplus`, `cxx20` from C++20 on) or C on `target`.
    #[allow(clippy::fn_params_excessive_bools)]
    pub fn new(cplusplus: bool, cxx20: bool, exceptions: bool, rtti: bool, target: Target) -> Self {
        StubFeatures { cplusplus, cxx20, exceptions, rtti, target }
    }

    fn lookup(&self, query: &str, name: &str) -> u32 {
        let Ok(i) = table::TABLE.binary_search_by(|e| (e.0, e.1).cmp(&(query, name))) else {
            return 0;
        };
        let (_, _, cxx, c) = table::TABLE[i];
        if !self.cplusplus {
            return c;
        }
        match name {
            // C++20-only answers (the table holds C++26's).
            "__builtin_coro_noop" | "modules" if !self.cxx20 => 0,
            "cxx_exceptions" if !self.exceptions => 0,
            "cxx_rtti" if !self.rtti => 0,
            _ => cxx,
        }
    }
}

impl FeatureQueries for StubFeatures {
    fn has_feature(&self, name: &str) -> bool {
        self.lookup("has_feature", name) != 0
    }

    fn has_extension(&self, name: &str) -> bool {
        self.lookup("has_extension", name) != 0 || self.has_feature(name)
    }

    fn has_builtin(&self, name: &str) -> u32 {
        self.lookup("has_builtin", name)
    }

    fn has_constexpr_builtin(&self, name: &str) -> bool {
        self.lookup("has_constexpr_builtin", name) != 0
    }

    fn has_attribute(&self, name: &str) -> u32 {
        self.lookup("has_attribute", name)
    }

    fn has_cpp_attribute(&self, scope: Option<&str>, name: &str) -> u32 {
        let full = scope.map_or_else(|| name.to_owned(), |s| format!("{s}::{name}"));
        match self.lookup("has_cpp_attribute", &full) {
            0 if self.cplusplus => NoFeatures.has_cpp_attribute(scope, name),
            v => v,
        }
    }

    fn has_declspec_attribute(&self, name: &str) -> bool {
        self.lookup("has_declspec_attribute", name) != 0
    }

    fn is_target(&self, query: TargetQuery, name: &str) -> bool {
        let t = &self.target;
        match query {
            TargetQuery::Arch => name.eq_ignore_ascii_case(t.arch),
            TargetQuery::Vendor => name.eq_ignore_ascii_case("unknown"),
            TargetQuery::Os => name.eq_ignore_ascii_case("linux"),
            TargetQuery::Environment => name.eq_ignore_ascii_case("gnu"),
            TargetQuery::VariantOs | TargetQuery::VariantEnvironment => false,
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn table_is_sorted() {
        assert!(table::TABLE.windows(2).all(|w| (w[0].0, w[0].1) < (w[1].0, w[1].1)));
    }

    #[test]
    fn answers() {
        let t = Target::parse("aarch64-unknown-linux-gnu").unwrap();
        let f = StubFeatures::new(true, true, true, true, t);
        assert_eq!(f.has_builtin("__remove_cvref"), 1);
        assert_eq!(f.has_cpp_attribute(None, "deprecated"), 201_309);
        assert_eq!(f.has_cpp_attribute(None, "nodiscard"), 201_907);
        assert!(f.has_feature("cxx_exceptions"));
        assert!(f.is_target(TargetQuery::Arch, "aarch64"));
        let c = StubFeatures::new(false, false, false, false, t);
        assert!(!c.has_feature("cxx_exceptions"));
    }
}
